Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
(* [comment removed for export] *)
Local Ltac norm_regset ::=
  repeat match goal with
  | |- context [@bvmap_set 5 word ?r ?v ?R] =>
      lazymatch R with TNode _ _ _ => idtac | TEmpty => idtac end;
      let p := eval vm_compute in (bv_key r) in
      change (@bvmap_set 5 word r v R) with (tset p v R);
      cbv beta iota delta [tset mkR]
  end.

(* [comment removed for export] *)
Definition vp_k_exit (ra sp gp tp t0 t1 t2 s0 s1 a0 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (m : mem)
  : machine_state -> Prop :=
  fun ms' => exists (a1' t3' t4' t5' t6' : word) (F' : bvmap 5 word) (fc' : bv 32) (s' n' : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1' a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
             F' (Z_to_bv 64 0xcfc6c) fc' None m (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ acc_regs F' s' n' /\ bc_avg 21 s' n'.
Lemma vp_k_loop : forall (n : nat) (kk : Z) (p : hpp) (ks rs : Z -> Z) (LT J : Z)
    (ra sp gp tp s0 a0 a1 a2 a4 a5 a6 a7 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (s n0 : Z),
  Z.of_nat n = 21 - kk -> 0 <= kk -> (1 <= n)%nat -> hp_ok p -> frm0 fc ->
  hp_DT p + 40 * hp_wpl p <= LT -> LT + 44 * hp_wpl p <= hp_DT p + hp_N p -> 11 <= J < 4 * hp_wpl p ->
  wr_at asegs m (hp_DT p) (hp_N p) -> acc asegs m (hp_DT p) (hp_N p) -> hp_kcells p ks rs m -> mem_inv asegs m ->
  acc_regs F s n0 -> bc_avg kk s n0 ->
  evt asegs (vp_k_exit ra sp gp tp (Z_to_bv 64 J) (Z_to_bv 64 0) (Z_to_bv 64 0) s0 (Z_to_bv 64 (hp_S1 p)) a0 a2 (Z_to_bv 64 LT) a4 a5 a6 a7
               (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (hp_wpl p)) (Z_to_bv 64 3) (Z_to_bv 64 1)
               (Z_to_bv 64 (18446744073709551615 - hp_RR p)) (Z_to_bv 64 1) (Z_to_bv 64 10) (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_SP p)) F m)
    (MS (mkR ra sp gp tp (Z_to_bv 64 J) (Z_to_bv 64 0) (Z_to_bv 64 0) s0 (Z_to_bv 64 (hp_S1 p)) a0 a1 a2 (Z_to_bv 64 LT) a4 a5 a6 a7
             (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (hp_wpl p)) (Z_to_bv 64 3) (Z_to_bv 64 1)
             (Z_to_bv 64 (18446744073709551615 - hp_RR p)) (Z_to_bv 64 1) (Z_to_bv 64 10) (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_SP p))
             (Z_to_bv 64 (kk - 10)) t4 t5 t6)
