Definition vp_j_exit (p : hpp) (DD ND wpld i : Z) (sp gp tp s0 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a1' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR (Z_to_bv 64 11) sp gp tp t0' t1' t2' s0 (Z_to_bv 64 (hp_S1 p)) (Z_to_bv 64 wpld) a1' (Z_to_bv 64 i) a3' a4' a5' a6' a7'
                  (Z_to_bv 64 (hp_RR p)) (Z_to_bv 64 2147450880) (Z_to_bv 64 (hp_wpl p)) (Z_to_bv 64 3) (Z_to_bv 64 1)
                  (Z_to_bv 64 (18446744073709551615 - hp_RR p)) (Z_to_bv 64 1) (Z_to_bv 64 10) (Z_to_bv 64 (hp_c p)) (Z_to_bv 64 (hp_SP p))
                  t3' t4' t5' t6')
             F' (Z_to_bv 64 0xcfa4c) fc' None m' (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ munch [(DD, DD + ND)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.
Lemma vp_j_loop : forall (n : nat) (p : hpp) (ks rs : Z -> Z) (DD ND wpld i j : Z)
